import{$ as e,A as t,B as n,V as r}from"./chunks/framework.DrAJjmzW.js";var i=JSON.parse(`{"title":"Utilities","description":"","frontmatter":{"title":"Utilities","hide":["navigation"]},"headers":[],"relativePath":"utilities.md","filePath":"utilities.md","lastUpdated":1788401923000}`),a={name:`utilities.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="utilities-page" tabindex="-1">Utilities Page <a class="header-anchor" href="#utilities-page" aria-label="Permalink to “Utilities Page”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Comprehensive System Utilities</p><p>The Utilities page provides direct access to system maintenance tools and settings management with intuitive controls. All utilities run PowerShell scripts behind the scenes and sync with your Windows configuration.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>The Utilities page offers 14 different system utilities. Each utility automatically detects your current system settings and provides appropriate controls - toggles, buttons, or dropdowns - to manage Windows features and perform maintenance tasks.</p><h2 id="available-utilities" tabindex="-1">Available Utilities <a class="header-anchor" href="#available-utilities" aria-label="Permalink to “Available Utilities”">​</a></h2><table tabindex="0"><thead><tr><th>Utility</th><th>Description</th><th>Control Type</th></tr></thead><tbody><tr><td><strong>Disk Cleaner</strong></td><td>Free up space by removing unnecessary files.</td><td>Button - &quot;Clean Now&quot;</td></tr><tr><td><strong>Storage Sense</strong></td><td>Automatically free up space by getting rid of files you don&#39;t need.</td><td>Toggle</td></tr><tr><td><strong>System Information</strong></td><td>View detailed information about your system.</td><td>Button - &quot;View Info&quot;</td></tr><tr><td><strong>Fast Startup</strong></td><td>Improve boot times by optimizing startup settings.</td><td>Toggle</td></tr><tr><td><strong>Windows Updates</strong></td><td>Control how Windows handles automatic updates.</td><td>Dropdown - [Default, Manual, Disabled]</td></tr><tr><td><strong>Graphics Driver</strong></td><td>Restart your graphics driver to fix display issues.</td><td>Button - &quot;Restart&quot;</td></tr><tr><td><strong>Power Plan</strong></td><td>Choose how your computer manages power and performance.</td><td>Dropdown - [Balanced, High Performance, Power Saver, Ultimate Performance]</td></tr><tr><td><strong>Flush DNS Cache</strong></td><td>Fix connection issues by clearing DNS resolver cache.</td><td>Button - &quot;Flush&quot;</td></tr><tr><td><strong>System File Checker</strong></td><td>Repair corrupted system files to improve stability.</td><td>Button - &quot;Repair&quot;</td></tr><tr><td><strong>DISM Health Restore</strong></td><td>Use DISM to repair the Windows image and fix system issues.</td><td>Button - &quot;Repair&quot;</td></tr><tr><td><strong>Check Disk</strong></td><td>Check and fix disk errors on your system.</td><td>Button - &quot;Check&quot;</td></tr><tr><td><strong>Restart Audio Service</strong></td><td>Fix sound issues by restarting Windows Audio.</td><td>Button - &quot;Restart&quot;</td></tr><tr><td><strong>Network Reset</strong></td><td>Reset your network stack to fix connectivity problems.</td><td>Button - &quot;Reset&quot;</td></tr><tr><td><strong>Windows Search and UI</strong></td><td>Restart Windows Search and UI to fix display issues.</td><td>Button - &quot;Restart&quot;</td></tr></tbody></table><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How It Works”">​</a></h2><ul><li><strong>Toggle</strong>: Enable/disable features with a switch. Automatically detects current state.</li><li><strong>Button</strong>: Execute one-time actions like cleaning, repairing, or restarting services.</li><li><strong>Dropdown</strong>: Choose from multiple options for settings with more than two states.</li></ul><p>All utilities automatically check your current system settings on page load and show toast notifications for success/failure. PowerShell scripts run in the background to apply changes.</p>`,9)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};